"""The keyed 670 (config/circuits/fairchild_670_keyed.yaml, generated by
scripts/derive_keyed_670.py; docs/SIDECHAIN_PLAN.md, K1): the stock 670 with a KEY INT /
EXT switch ahead of T103's primary. INT is the stock circuit beside a terminated jack;
EXT keys the sidechain from the control input `key`. The renders run at draft-1x (the
profile, varimu.measure.keyed_suite, measures the unit at production).
"""

import dataclasses
import importlib.util

import pytest

from varimu.circuit import builder, spec
from varimu.config import REPO_ROOT
from varimu.measure import keyed_suite as ks
from varimu.preflight import check_circuit
from varimu.sim.io import TransientSettings

JACK = {"RKEY", "RKT"}  # the terminated jack's parts at INT


def _derive():
    path = REPO_ROOT / "scripts" / "derive_keyed_670.py"
    sp = importlib.util.spec_from_file_location("derive_keyed_670", path)
    mod = importlib.util.module_from_spec(sp)
    sp.loader.exec_module(mod)
    return mod


def test_the_generated_file_is_current():
    mod = _derive()
    assert mod.OUT.read_text(encoding="utf-8") == mod.derive(), (
        "rerun `uv run python scripts/derive_keyed_670.py`"
    )


def test_passes_the_preflight_checks_at_both_positions():
    c = spec.load_circuit(spec.circuit_path("fairchild_670_keyed"))
    assert c.cv_inputs == (("key", "key_src"),)
    assert check_circuit(c) == []


def test_int_is_the_stock_circuit_beside_the_terminated_jack():
    stock = builder.build(spec.load_circuit(spec.circuit_path("fairchild_670")), {}).ir
    keyed = builder.build(spec.load_circuit(spec.circuit_path("fairchild_670_keyed")), {}).ir

    def without_jack(ir):
        return [
            dataclasses.replace(s, elements=tuple(e for e in s.elements if e.name not in JACK))
            for s in ir.sections
        ]

    assert without_jack(keyed) == list(stock.sections)
    ext = builder.build(
        spec.load_circuit(spec.circuit_path("fairchild_670_keyed")), {"key_mode": 1}
    ).ir
    sc = next(s for s in ext.sections if s.title == "sidechain input")
    names = {e.name: e for e in sc.elements}
    assert "R145" not in names and "RKT" not in names
    assert {names["R145K"].a, names["R145K"].b} == {"key", "s1"}


@pytest.fixture(scope="module")
def bench():
    pytest.importorskip("circuitsim", reason="needs `uv sync --extra fast`")
    s = TransientSettings.from_sim_settings(engine="circuitsim", quality="draft-1x")
    return ks.Bench({}, s)


def test_int_renders_as_the_stock_670_whatever_the_key(bench):
    fs = bench.fs
    tone = ks.sine(1000.0, -6.0, 0.6, fs)
    keys = ks.kick([0.1, 0.35], 6.0, 0.6, fs)
    stock, at_int = bench.run(
        [bench.job(tone, None, {}, stock=True), bench.job(tone, keys, {"key_mode": 0})]
    )
    a = int(0.05 * fs)
    assert ks.rel_rms_db(at_int["out"][a:], stock["out"][a:]) < -100.0


def test_ext_ducks_the_bass_under_a_kick_and_recovers(bench):
    fs = bench.fs
    n_s = ks.PRE_S + 1.0
    bass = ks.sine(ks.BASS_HZ, ks.BASS_DBFS, n_s, fs)
    quiet, loud = bench.run(
        [
            bench.job(bass, ks.kick([ks.PRE_S], -12.0, n_s, fs), {"key_mode": 1}),
            bench.job(bass, ks.kick([ks.PRE_S], 0.0, n_s, fs), {"key_mode": 1, "time_constant": 1}),
        ]
    )
    q = ks.duck_of(quiet, ks.PRE_S, fs, n_s)
    d = ks.duck_of(loud, ks.PRE_S, fs, n_s)
    assert q["deepest_db"] > -1.0  # 12 dB under the reference: below the threshold
    assert d["deepest_db"] < -10.0
    assert d["back_to_1db_s"] is not None and d["back_to_1db_s"] < 0.6  # TC1's release


def test_depth_bounds_the_duck_and_leaves_the_idle_alone(bench):
    # A kick 6 dB over the reference: without the limit (DEPTH 1) it cuts the bass off; at
    # DEPTH 0.15 the duck stays within a few dB; at idle DEPTH changes nothing.
    fs = bench.fs
    n_s = ks.PRE_S + 1.0
    bass = ks.sine(ks.BASS_HZ, ks.BASS_DBFS, n_s, fs)
    kick = ks.kick([ks.PRE_S], 6.0, n_s, fs)
    full, shallow, idle_0, idle_1 = bench.run(
        [
            bench.job(bass, kick, {"key_mode": 1, "key_depth": 1.0}),
            bench.job(bass, kick, {"key_mode": 1, "key_depth": 0.15}),
            bench.job(bass, None, {"key_mode": 1, "key_depth": 0.0}),
            bench.job(bass, None, {"key_mode": 1, "key_depth": 1.0}),
        ]
    )
    assert ks.duck_of(full, ks.PRE_S, fs, n_s)["deepest_db"] < -40.0
    d = ks.duck_of(shallow, ks.PRE_S, fs, n_s)["deepest_db"]
    assert -8.0 < d < -2.0, d
    a = int(0.5 * fs)
    assert ks.rel_rms_db(idle_0["out"][a:], idle_1["out"][a:]) < -60.0


def test_the_suite_is_registered():
    from varimu.measure import profiles

    assert profiles.profile("fairchild_670_keyed").run is not None
    assert importlib.util.find_spec("varimu.measure.keyed_suite") is not None
